<section class="admin-content"><div class="admin-welcome"><div><span class="eyebrow">ন্যায্যতা ও জবাবদিহি</span><h2>আপত্তি ও অপসারণের অনুরোধ</h2><p>প্রতিটি অনুরোধ ব্যক্তিগতভাবে পর্যালোচনা করুন।</p></div></div>
<?php if ($appeals): ?><div class="admin-report-grid"><?php foreach ($appeals as $appeal): ?>
  <?php $hasCard = !empty($appeal['slug']); $canArchiveCard = $appeal['appeal_type'] === 'takedown' && !empty($appeal['card_id']); ?>
  <article class="admin-report-card"><div class="admin-report-card-top"><span class="status-pill status-<?= e($appeal['status']) ?>"><?= e(['pending'=>'পেন্ডিং','reviewed'=>'রিভিউড','resolved'=>'সম্পন্ন'][$appeal['status']] ?? $appeal['status']) ?></span><span class="admin-report-date"><?= e(relativeDate($appeal['created_at'])) ?></span></div>
    <span class="eyebrow"><?= $appeal['appeal_type'] === 'takedown' ? 'অপসারণের অনুরোধ' : 'জবাব দেওয়ার অধিকার' ?></span><h2><?= e($appeal['sender_name']) ?></h2><p class="appeal-card-ref"><?php if ($hasCard): ?>কার্ড · <a href="<?= e(url('/card/' . $appeal['slug'])) ?>" target="_blank" rel="noopener noreferrer"><?= e($appeal['accused_name']) ?> ↗</a><?php else: ?>কার্ড-বহির্ভূত আপত্তি<?php endif; ?><?php if (!empty($appeal['reference_text'])): $referenceText = (string) $appeal['reference_text']; $referenceHref = safeExternalUrl($referenceText) ? $referenceText : (str_starts_with($referenceText, '/') ? url($referenceText) : ''); ?><br>রেফারেন্স · <?php if ($referenceHref !== ''): ?><a href="<?= e($referenceHref) ?>" target="_blank" rel="noopener noreferrer nofollow"><?= e($referenceText) ?> ↗</a><?php else: ?><?= e($referenceText) ?><?php endif; ?><?php endif; ?></p><p><?= nl2br(e($appeal['message'])) ?></p><a class="text-link" href="mailto:<?= e($appeal['sender_email']) ?>"><?= e($appeal['sender_email']) ?></a>
    <?php if (!empty($appeal['whatsapp_number'])): ?><a class="text-link" href="https://wa.me/<?= e(preg_replace('/\D+/', '', (string) $appeal['whatsapp_number'])) ?>" target="_blank" rel="noopener noreferrer">WhatsApp · <?= e($appeal['whatsapp_number']) ?> ↗</a><?php endif; ?>
    <?php if ($appeal['status'] !== 'resolved'): ?><form class="appeal-admin-actions" method="post" action="<?= e(url('/admin/appeals/' . (int) $appeal['id'] . '/' . ($canArchiveCard ? 'archive' : 'resolve'))) ?>"><?= csrfField() ?><label class="field-label">মডারেটরের নোট<textarea name="admin_note" rows="2" maxlength="1000"></textarea></label><button class="button <?= $canArchiveCard ? 'button-danger' : 'button-dark' ?>" type="submit"><?= $canArchiveCard ? 'কার্ড আর্কাইভ করে সম্পন্ন' : 'অনুরোধ সম্পন্ন' ?></button></form><?php endif; ?>
  </article>
<?php endforeach; ?></div><?php else: ?><div class="admin-empty large"><div class="empty-symbol">↗</div><h2>এখনো কোনো আপিল নেই</h2><p>কার্ডে বা সাইট-বহির্ভূত ফর্মে পাঠানো আপত্তি এখানে দেখা যাবে।</p></div><?php endif; ?></section>
